package kr.danta.core.nation;
import kr.danta.core.state.GameState;import kr.danta.core.territory.*;import org.junit.jupiter.api.Test;import java.util.Map;import static org.junit.jupiter.api.Assertions.*;
class Dev095VassalServiceTest{private GameState game(){GameState g=new GameState();g.addNation(new NationState("red","red","red_capital",100,NationStatus.ACTIVE));g.addNation(new NationState("blue","blue","blue_capital",100,NationStatus.ACTIVE));g.addStrategicPoint(new StrategicPoint("red_capital","red cap",StrategicPointType.CAPITAL,"blue",new PointPosition("world",0,64,0),1,Map.of()));g.addStrategicPoint(new StrategicPoint("red_farm","farm",StrategicPointType.FARM,"red",new PointPosition("world",1,64,0),1,Map.of()));return g;}
@Test void capitalFallCreatesVassalWithoutTransferringOtherTerritory(){GameState g=game();VassalService s=new VassalService(g);var r=s.onCapitalFallen("red","blue",1234);assertEquals("blue",r.overlordNationId());assertEquals(NationStatus.VASSAL,g.nation("red").orElseThrow().status());assertEquals("red",g.strategicPoint("red_farm").orElseThrow().ownerNationId().orElseThrow());}
@Test void victorMustActuallyControlCapital(){GameState g=game();g.strategicPoint("red_capital").orElseThrow().setOwnerNationId("red");VassalService s=new VassalService(g);assertThrows(IllegalStateException.class,()->s.onCapitalFallen("red","blue",1));}
@Test void relationRestores(){GameState g=game();VassalService s=new VassalService(g);s.restore(new VassalRelation("red","blue",77));assertEquals(NationStatus.VASSAL,g.nation("red").orElseThrow().status());assertEquals(77,s.relation("red").orElseThrow().vassalizedAtRuntimeMillis());}}
